 save(){if(!this.journey||!this.active||!this.owns())return false;try{if(this.journey.practice){saveMemory(this.storage,this.parentJourney,this.journey);this.$('side-save-status').textContent='Guardian memory saved · your journey waits in its room';return true;}saveSide(this.storage,this.journey);if(this.journey.pendingBank){this.onBank(this.journey.pendingBank);this.journey.pendingBank=null;saveSide(this.storage,this.journey);}this.$('side-save-status').textContent='Side journey saved on this device';return true;}catch{this.$('side-save-status').textContent=this.journey.pendingBank?'Deposit waiting · saved receipt will retry on return':'Save unavailable · keep this page open';return false;}}
